{ printf '%s' "$HEAD"; cat "$SRC/index.html"; printf '</body></html>'; } > "$P/$NAME/index.html"
cp "$SRC/tap-worklet.js" "$P/$NAME/" ; cp "$SRC/tap-worklet.js" "$P/$NAME-inst/"
python3 - "$P/$NAME/index.html" "$P/$NAME-inst/index.html" <<'PY'
